import{_ as t,o,c as n,a0 as i}from"./chunks/framework.DQOulFGV.js";const h=JSON.parse('{"title":"Developer Guide & Technical Reference","description":"","frontmatter":{},"headers":[],"relativePath":"docs/dev_guide/overview.md","filePath":"docs/dev_guide/overview.md"}'),r={name:"docs/dev_guide/overview.md"};function a(s,e,l,d,c,g){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="developer-guide-technical-reference" tabindex="-1">Developer Guide &amp; Technical Reference <a class="header-anchor" href="#developer-guide-technical-reference" aria-label="Permalink to &quot;Developer Guide &amp; Technical Reference&quot;">​</a></h1><h2 id="_1-integrations" tabindex="-1">1. Integrations <a class="header-anchor" href="#_1-integrations" aria-label="Permalink to &quot;1. Integrations&quot;">​</a></h2><p>The platform relies on several external third-party services for its core functionality. All configuration must be handled through environment variables or secure secret managers, and no credentials are ever committed to the repository.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Service</th><th style="text-align:left;">Purpose</th><th style="text-align:left;">Configuration Method</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Google Gemini API</strong></td><td style="text-align:left;">Generative AI (RAG) for generating expert reports and farmer SMS prescriptions.</td><td style="text-align:left;">Requires <code>GOOGLE_API_KEY</code> and <code>GEMINI_MODEL</code> environment variables. API keys are stored in Secret Manager (prod) and <code>.env</code> (dev).</td></tr><tr><td style="text-align:left;"><strong>Gemini File Search Store</strong></td><td style="text-align:left;">Hosts the agricultural knowledge base for semantic retrieval.</td><td style="text-align:left;">Created via REST API using <code>gemini-embedding-2</code>. Configured in the Jupyter setup script.</td></tr><tr><td style="text-align:left;"><strong>Heroku PostgreSQL</strong></td><td style="text-align:left;">Primary production database storing users, tickets, diagnostics, and AI audit logs.</td><td style="text-align:left;"><code>DATABASE_URL</code> provided by Heroku add-on. Used by backend migrations and ORM.</td></tr><tr><td style="text-align:left;"><strong>SMS Leopard</strong></td><td style="text-align:left;">SMS gateway for delivering fertilizer recommendations and alerts to farmers.</td><td style="text-align:left;">Requires <code>SMS_LEOPARD_API_KEY</code>, <code>SMS_LEOPARD_API_SECRET</code>, and <code>SMS_LEOPARD_SENDER_ID</code>. Uses Basic Auth.</td></tr><tr><td style="text-align:left;"><strong>Cloudflare</strong></td><td style="text-align:left;">Edge security (WAF, DDoS protection, TLS termination).</td><td style="text-align:left;">Configured via Cloudflare DNS. Points domain to Vercel and Heroku.</td></tr><tr><td style="text-align:left;"><strong>Vercel</strong></td><td style="text-align:left;">Hosting for the Supervisor PWA and the Field Expert Mobile Interface (PWA).</td><td style="text-align:left;">Connected via Git integrations. Uses <code>vercel.json</code> for rewrites and build settings.</td></tr></tbody></table><hr><h2 id="_2-code-standards" tabindex="-1">2. Code Standards <a class="header-anchor" href="#_2-code-standards" aria-label="Permalink to &quot;2. Code Standards&quot;">​</a></h2><p>The team follows strict conventions to maintain code quality, security, and readability across the codebase.</p><h3 id="_2-1-naming-conventions" tabindex="-1">2.1 Naming Conventions <a class="header-anchor" href="#_2-1-naming-conventions" aria-label="Permalink to &quot;2.1 Naming Conventions&quot;">​</a></h3><ul><li><strong>Backend (Python):</strong> <code>snake_case</code> for variables and functions, <code>PascalCase</code> for classes. Constants use <code>UPPER_CASE</code>.</li><li><strong>Frontend (TypeScript/React):</strong> <code>camelCase</code> for variables and functions, <code>PascalCase</code> for components and classes.</li><li><strong>Files:</strong> <code>snake_case.py</code> for backend modules; <code>PascalCase.tsx</code> for frontend components.</li><li><strong>Branches:</strong> Feature branches use <code>feature/[short-description]</code>, bug fixes use <code>fix/[short-description]</code>, and hotfixes use <code>hotfix/[short-description]</code> (e.g., <code>feature/soil-form-compression</code>).</li></ul><h3 id="_2-2-folder-and-file-structure" tabindex="-1">2.2 Folder and File Structure <a class="header-anchor" href="#_2-2-folder-and-file-structure" aria-label="Permalink to &quot;2.2 Folder and File Structure&quot;">​</a></h3><p>Adhere to the strict folder layout to ensure separation of concerns:</p><ul><li><strong>Backend:</strong> <code>backend/app/routes/</code> contains API routers, <code>backend/app/models/</code> for database models, <code>backend/app/schemas/</code> for Pydantic schemas, and <code>backend/app/services/</code> for business logic.</li><li><strong>Frontend:</strong> <code>frontend/src/components/</code> for reusable UI components, <code>frontend/src/screens/</code> for page-level views, and <code>frontend/src/services/</code> for API integrations.</li><li><strong>Rule for New Code:</strong> All new feature code must reside in its corresponding layer folder. No business logic is permitted inside route or component files; it must be extracted into services.</li></ul><h3 id="_2-3-formatting-and-linting" tabindex="-1">2.3 Formatting and Linting <a class="header-anchor" href="#_2-3-formatting-and-linting" aria-label="Permalink to &quot;2.3 Formatting and Linting&quot;">​</a></h3><ul><li><strong>Backend:</strong> <code>black</code> for auto-formatting and <code>ruff</code> for linting. The configuration is located in <code>pyproject.toml</code>.</li><li><strong>Frontend:</strong> <code>ESLint</code> and <code>Prettier</code>. The configuration is located in <code>.eslintrc.js</code> and <code>.prettierrc</code>.</li><li><strong>Validation:</strong> All code must pass <code>ruff check</code> and <code>eslint</code> without errors before merging.</li></ul><h3 id="_2-4-commit-messages-and-pull-requests" tabindex="-1">2.4 Commit Messages and Pull Requests <a class="header-anchor" href="#_2-4-commit-messages-and-pull-requests" aria-label="Permalink to &quot;2.4 Commit Messages and Pull Requests&quot;">​</a></h3><ul><li><strong>Commit Format:</strong> Follow the Conventional Commits standard: <code>type(scope): description</code> (e.g., <code>fix(auth): handle session token expiration</code>). Types include: <code>feat</code>, <code>fix</code>, <code>docs</code>, <code>style</code>, <code>refactor</code>, <code>test</code>, <code>chore</code>.</li><li><strong>Pull Request Rules:</strong><ul><li>Must target the <code>main</code> branch from a short-lived feature branch.</li><li>Requires at least one reviewer approval.</li><li>Must pass all CI/CD checks (linting, unit tests, build).</li><li>PR titles must mirror the merge commit message (e.g., <code>feat(tickets): add cancel flow</code>).</li></ul></li></ul><h3 id="_2-5-error-handling-and-logging" tabindex="-1">2.5 Error Handling and Logging <a class="header-anchor" href="#_2-5-error-handling-and-logging" aria-label="Permalink to &quot;2.5 Error Handling and Logging&quot;">​</a></h3><ul><li><strong>Backend:</strong> All exceptions are handled in the service layer and returned as structured HTTP responses. Logging is performed using the <code>logging</code> module (standard Python) with specific file logs in the backend.</li><li><strong>Frontend:</strong> Unhandled exceptions are caught via Error Boundaries in React. Logging is performed via <code>console.error</code> during development and routed to the backend monitoring tools in production.</li><li><strong>Convention:</strong> Never log passwords, API keys, or full personal data. Use structured log messages with adequate context (e.g., <code>Logger.error(&quot;Failed to create ticket for user: {user_id}&quot;, extra={&quot;user_id&quot;: user_id})</code>).</li></ul><h3 id="_2-6-comment-and-docstring-style" tabindex="-1">2.6 Comment and Docstring Style <a class="header-anchor" href="#_2-6-comment-and-docstring-style" aria-label="Permalink to &quot;2.6 Comment and Docstring Style&quot;">​</a></h3><ul><li><strong>Backend:</strong> Use <strong>Google-style docstrings</strong> for all public modules, classes, and functions. Inline comments should be used to explain complex logic or business rules.</li><li><strong>Frontend:</strong> Use <strong>JSDoc</strong> comments for exported functions and complex components. Inline comments should explain any complex or non-obvious logic.</li><li><strong>Convention:</strong> Comments must explain &quot;why&quot; code exists, not &quot;what&quot; the code is doing. No commented-out code is allowed in the <code>main</code> branch.</li></ul><hr><h2 id="_3-testing-conventions-rules" tabindex="-1">3. Testing Conventions &amp; Rules <a class="header-anchor" href="#_3-testing-conventions-rules" aria-label="Permalink to &quot;3. Testing Conventions &amp; Rules&quot;">​</a></h2><p>This section outlines the strict rules and conventions for writing and maintaining test suites. It is not a &quot;how to run tests&quot; guide, but rather the architectural and naming standards the team must adhere to when contributing new tests.</p><h3 id="_3-1-test-structure-location" tabindex="-1">3.1 Test Structure &amp; Location <a class="header-anchor" href="#_3-1-test-structure-location" aria-label="Permalink to &quot;3.1 Test Structure &amp; Location&quot;">​</a></h3><ul><li><strong>Backend (Pytest):</strong><ul><li>All tests must be located in <code>backend/tests/</code>.</li><li>Unit tests go in <code>backend/tests/unit/</code> and integration tests go in <code>backend/tests/integration/</code>.</li></ul></li><li><strong>Frontend (Jest/Vitest):</strong><ul><li>Test files must be colocated with the component or service they test (e.g., <code>Header.test.tsx</code> next to <code>Header.tsx</code>), or organized in a dedicated <code>__tests__</code> folder if the project grows larger.</li></ul></li><li><strong>Rule:</strong> Test files must never be placed in the production source folder (<code>src/</code> or <code>app/</code>).</li></ul><h3 id="_3-2-naming-conventions" tabindex="-1">3.2 Naming Conventions <a class="header-anchor" href="#_3-2-naming-conventions" aria-label="Permalink to &quot;3.2 Naming Conventions&quot;">​</a></h3><ul><li><strong>Backend (Pytest):</strong> Test files are named <code>test_[module_name].py</code>. Test functions use <code>test_[behavior_description]_[expected_outcome]</code> (e.g., <code>test_create_farmer_returns_201</code>).</li><li><strong>Frontend (Jest):</strong> Test files are named <code>[component_name].test.tsx</code>.</li><li><strong>Rule:</strong> Test names must be descriptive and state exactly what is being tested and the expected outcome.</li></ul><h3 id="_3-3-data-isolation-mocking" tabindex="-1">3.3 Data Isolation &amp; Mocking <a class="header-anchor" href="#_3-3-data-isolation-mocking" aria-label="Permalink to &quot;3.3 Data Isolation &amp; Mocking&quot;">​</a></h3><ul><li><strong>Rule:</strong> All logic tests must use mocked external services (APIs, SMS gateways, AI models) and must not rely on live database connections.</li><li><strong>Rule:</strong> Unit tests must be deterministic and run without network access. Integration tests must explicitly state if they require a live local database.</li></ul><h3 id="_3-4-coverage-requirements" tabindex="-1">3.4 Coverage Requirements <a class="header-anchor" href="#_3-4-coverage-requirements" aria-label="Permalink to &quot;3.4 Coverage Requirements&quot;">​</a></h3><ul><li><strong>Backend:</strong> The minimum required coverage is 80% for all new business logic.</li><li><strong>Frontend:</strong> All critical user flows (login, ticket resolution, offline sync) must be tested.</li><li><strong>Rule:</strong> Any new feature or bug fix must include corresponding test cases to maintain the coverage threshold.</li></ul><h3 id="_3-5-test-categories-matrices" tabindex="-1">3.5 Test Categories &amp; Matrices <a class="header-anchor" href="#_3-5-test-categories-matrices" aria-label="Permalink to &quot;3.5 Test Categories &amp; Matrices&quot;">​</a></h3><p>The comprehensive QA test suite covers extensive functional, boundary, negative, and end-to-end scenarios across the platform. These tests are documented in external spreadsheets and test suites (e.g., Postman, Cypress, Playwright, and manual QA sheets).</p><h2 id="_4-0-glossary" tabindex="-1">4.0 Glossary <a class="header-anchor" href="#_4-0-glossary" aria-label="Permalink to &quot;4.0 Glossary&quot;">​</a></h2><h3 id="_4-1-technical-acronyms" tabindex="-1">4.1 Technical Acronyms <a class="header-anchor" href="#_4-1-technical-acronyms" aria-label="Permalink to &quot;4.1 Technical Acronyms&quot;">​</a></h3><ul><li><strong>API:</strong> A defined set of rules that allows different software applications to communicate with each other.</li><li><strong>CI/CD:</strong> A practice where code changes are automatically built, tested, and deployed to production.</li><li><strong>DPA:</strong> A legally binding contract between a data controller and processor outlining data handling responsibilities.</li><li><strong>HMAC:</strong> A cryptographic signature used to verify the authenticity and integrity of an incoming message.</li><li><strong>HTTPS:</strong> The secure version of HTTP that encrypts data transmitted between a user and a server.</li><li><strong>JWT:</strong> A compact, URL-safe token used for stateless authentication and role verification.</li><li><strong>MFA:</strong> A security mechanism requiring multiple verification factors to access a resource.</li><li><strong>ODPC:</strong> The Kenyan regulatory authority established to oversee data protection compliance.</li><li><strong>PWA:</strong> A web-based application that works offline and can be installed on a device like a native app.</li><li><strong>RAG:</strong> An AI architecture that retrieves external knowledge to ground responses and reduce hallucinations.</li><li><strong>RBAC:</strong> A security model where access permissions are granted based on the user&#39;s role within an organization.</li><li><strong>SAST:</strong> A white-box testing method that analyzes source code to find security vulnerabilities early.</li><li><strong>SQL:</strong> A domain-specific language used for managing and querying data in relational databases.</li><li><strong>TLS:</strong> A cryptographic protocol used to secure communications over a computer network.</li><li><strong>UI/UX:</strong> The visual design and overall user experience of an application.</li><li><strong>WAF:</strong> A firewall that filters and monitors HTTP traffic to protect against common web attacks.</li></ul><h3 id="_4-2-domain-definitions-auditerra" tabindex="-1">4.2 Domain Definitions (Auditerra) <a class="header-anchor" href="#_4-2-domain-definitions-auditerra" aria-label="Permalink to &quot;4.2 Domain Definitions (Auditerra)&quot;">​</a></h3><ul><li><strong>Agroecological Zone:</strong> A region defined by specific climate, soil, and crop suitability characteristics.</li><li><strong>Diagnostic Log:</strong> A digital record containing soil measurements and observations captured during a field visit.</li><li><strong>Field Expert:</strong> A certified agricultural professional who visits farms and collects on-site soil data.</li><li><strong>Institutional Supervisor:</strong> A stakeholder who oversees program impact, expert deployment, and audit reporting.</li><li><strong>Knowledge Base:</strong> A curated collection of project-specific agricultural documents used to ground AI responses.</li><li><strong>Security Handshake:</strong> A one-time SMS code entered by the expert to verify their physical presence at the farm.</li><li><strong>Ticket:</strong> A central digital workflow object that tracks a farmer&#39;s issue from reporting to resolution.</li></ul>',38)])])}const m=t(r,[["render",a]]);export{h as __pageData,m as default};
